import 'dart:io';
import 'dart:typed_data';

import 'cloud_sync.dart' show Shizuku;

// Installs Switch updates and DLC straight into Eden's NAND, the way Eden's
// own "Install content" does, but without touching its UI. Eden keeps
// installed content under nand/user/Contents/registered/000000XX/<ncaId>.nca
// where XX is the first byte of SHA-256(ncaId), and title keys from tickets in
// keys/title.keys_autogenerated as "<rightsId> = <key>". Both were verified
// against files Eden installed itself.

/// Eden package IDs whose data folder may hold a NAND. The Genshin-spoofed
/// build and the nightly are separate apps with separate NANDs, so content is
/// installed into every one that exists.
const kEdenPackages = [
  'com.miHoYo.Yuanshen',
  'com.miHoYo.Yuanshen.nightly',
  'dev.eden.eden_emulator',
  'dev.eden.eden_emulator.nightly',
  'org.yuzu.yuzu_emu',
];

String shq(String p) => "'${p.replaceAll("'", "'\\''")}'";

class Addon {
  final String relPath, name, kind, titleId;
  final int? version, sizeBytes;
  Addon(this.relPath, this.name, this.kind, this.titleId, this.version, this.sizeBytes);

  factory Addon.fromJson(Map j) => Addon(
        j['relPath'] ?? '',
        j['name'] ?? '',
        j['kind'] ?? '',
        j['titleId'] ?? '',
        j['version'] is int ? j['version'] : null,
        j['sizeBytes'] is int ? j['sizeBytes'] : null,
      );

  String get label => kind == 'update' ? 'update' : 'DLC';
}

class Pfs0Entry {
  final String name;
  final int offset, size;
  Pfs0Entry(this.name, this.offset, this.size);
  bool get isNca => name.endsWith('.nca');
  bool get isTicket => name.endsWith('.tik');
  String get ncaId => name.substring(0, 32).toLowerCase();
}

/// Reads the PFS0 (NSP) header: file count, string table and entry table.
/// Offsets are relative to the end of the header, which is what the caller
/// needs to slice the file with `tail -c`.
List<Pfs0Entry> readPfs0(String path) {
  final raf = File(path).openSync();
  try {
    final head = raf.readSync(16);
    if (head.length < 16 || String.fromCharCodes(head.sublist(0, 4)) != 'PFS0') {
      throw Exception('Not an NSP (missing PFS0 header): $path');
    }
    final bd = ByteData.sublistView(head);
    final count = bd.getUint32(4, Endian.little);
    final stringTableSize = bd.getUint32(8, Endian.little);
    if (count == 0 || count > 4096) throw Exception('Unreasonable NSP entry count $count');
    final entries = raf.readSync(count * 24);
    final strings = raf.readSync(stringTableSize);
    final headerSize = 16 + count * 24 + stringTableSize;
    final eb = ByteData.sublistView(entries);
    final out = <Pfs0Entry>[];
    for (var i = 0; i < count; i++) {
      final offset = eb.getUint64(i * 24, Endian.little);
      final size = eb.getUint64(i * 24 + 8, Endian.little);
      final nameOffset = eb.getUint32(i * 24 + 16, Endian.little);
      var end = strings.indexOf(0, nameOffset);
      if (end < 0) end = strings.length;
      out.add(Pfs0Entry(String.fromCharCodes(strings.sublist(nameOffset, end)), headerSize + offset, size));
    }
    return out;
  } finally {
    raf.closeSync();
  }
}

class TicketKey {
  final String rightsId, titleKey; // upper-case hex, 32 chars each
  TicketKey(this.rightsId, this.titleKey);
}

/// Common tickets carry the encrypted title key at 0x180 and the rights ID at
/// 0x2A0. Personalised tickets (type byte 0x141 == 1) need the console's
/// RSA key pair and are skipped; Eden would skip them too.
TicketKey? readTicket(String nspPath, Pfs0Entry tik) {
  if (tik.size < 0x2C0) return null;
  final raf = File(nspPath).openSync();
  try {
    raf.setPositionSync(tik.offset);
    final data = raf.readSync(0x2C0);
    if (data[0x141] != 0) return null;
    final key = data.sublist(0x180, 0x190);
    final rightsId = data.sublist(0x2A0, 0x2B0);
    if (rightsId.every((b) => b == 0)) return null;
    return TicketKey(hexUpper(rightsId), hexUpper(key));
  } finally {
    raf.closeSync();
  }
}

String hexUpper(List<int> bytes) =>
    bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join().toUpperCase();

/// Registered-cache folder for an NCA ID, mirroring Eden's
/// GetRelativePathFromNcaID: "000000" + first SHA-256 byte in upper hex.
String registeredDirFor(String ncaIdHex) {
  final id = Uint8List.fromList(List.generate(16, (i) => int.parse(ncaIdHex.substring(i * 2, i * 2 + 2), radix: 16)));
  final first = sha256(id)[0];
  return '000000${first.toRadixString(16).padLeft(2, '0').toUpperCase()}';
}

// Minimal SHA-256 (FIPS 180-4); the client has no package dependencies.
Uint8List sha256(Uint8List message) {
  const k = <int>[
    0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
    0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
    0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
    0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
    0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
    0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
    0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
    0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
  ];
  var h = <int>[0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19];
  final bitLen = message.length * 8;
  final padded = BytesBuilder()..add(message)..addByte(0x80);
  while ((padded.length + 8) % 64 != 0) {
    padded.addByte(0);
  }
  final lenBytes = ByteData(8)..setUint64(0, bitLen, Endian.big);
  padded.add(lenBytes.buffer.asUint8List());
  final data = padded.toBytes();
  final w = List<int>.filled(64, 0);
  int rotr(int x, int n) => ((x >> n) | (x << (32 - n))) & 0xffffffff;
  for (var chunk = 0; chunk < data.length; chunk += 64) {
    final bd = ByteData.sublistView(data, chunk, chunk + 64);
    for (var i = 0; i < 16; i++) {
      w[i] = bd.getUint32(i * 4, Endian.big);
    }
    for (var i = 16; i < 64; i++) {
      final s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
      final s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
      w[i] = (w[i - 16] + s0 + w[i - 7] + s1) & 0xffffffff;
    }
    var a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7];
    for (var i = 0; i < 64; i++) {
      final s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      final ch = (e & f) ^ ((~e & 0xffffffff) & g);
      final t1 = (hh + s1 + ch + k[i] + w[i]) & 0xffffffff;
      final s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      final maj = (a & b) ^ (a & c) ^ (b & c);
      final t2 = (s0 + maj) & 0xffffffff;
      hh = g; g = f; f = e; e = (d + t1) & 0xffffffff;
      d = c; c = b; b = a; a = (t1 + t2) & 0xffffffff;
    }
    h = [
      (h[0] + a) & 0xffffffff, (h[1] + b) & 0xffffffff, (h[2] + c) & 0xffffffff, (h[3] + d) & 0xffffffff,
      (h[4] + e) & 0xffffffff, (h[5] + f) & 0xffffffff, (h[6] + g) & 0xffffffff, (h[7] + hh) & 0xffffffff,
    ];
  }
  final out = ByteData(32);
  for (var i = 0; i < 8; i++) {
    out.setUint32(i * 4, h[i], Endian.big);
  }
  return out.buffer.asUint8List();
}

/// Plan for one NSP: which files to place where. Pure, so it can be unit
/// tested without a device.
class InstallPlan {
  final List<({Pfs0Entry entry, String relTarget})> ncas;
  final List<Pfs0Entry> tickets;
  InstallPlan(this.ncas, this.tickets);
}

InstallPlan planInstall(List<Pfs0Entry> entries) {
  final ncas = <({Pfs0Entry entry, String relTarget})>[];
  final tickets = <Pfs0Entry>[];
  for (final e in entries) {
    if (e.isNca && e.name.length >= 36) {
      // Eden stores the meta NCA as a plain <id>.nca too; the ".cnmt" tag is
      // only the NSP's naming convention.
      ncas.add((entry: e, relTarget: '${registeredDirFor(e.ncaId)}/${e.ncaId}.nca'));
    } else if (e.isTicket) {
      tickets.add(e);
    }
  }
  return InstallPlan(ncas, tickets);
}

class EdenContentInstaller {
  final void Function(String) log;
  EdenContentInstaller(this.log);

  Future<List<String>> findEdenDirs() async {
    final script = kEdenPackages
        .map((p) => "[ -d /sdcard/Android/data/$p/files/nand ] && echo /sdcard/Android/data/$p/files")
        .join('; ');
    final out = await Shizuku.run('$script; true');
    return out.split('\n').map((l) => l.trim()).where((l) => l.isNotEmpty).toList();
  }

  Future<void> stopEden() async {
    await Shizuku.run('${kEdenPackages.map((p) => 'am force-stop $p').join('; ')}; true');
  }

  Future<int?> _remoteSize(String path) async {
    final out = (await Shizuku.run("stat -c %s ${shq(path)} 2>/dev/null || true")).trim();
    return int.tryParse(out);
  }

  /// Installs one NSP into every Eden NAND found. Returns the number of NCAs
  /// written (0 means everything was already there).
  Future<int> installNsp(String nspPath, {List<String>? edenDirs}) async {
    final dirs = edenDirs ?? await findEdenDirs();
    if (dirs.isEmpty) throw Exception('No Eden installation with a NAND was found.');
    final plan = planInstall(readPfs0(nspPath));
    if (plan.ncas.isEmpty) throw Exception('NSP contains no NCA files: $nspPath');
    var written = 0;
    for (final dir in dirs) {
      final registered = '$dir/nand/user/Contents/registered';
      for (final item in plan.ncas) {
        final target = '$registered/${item.relTarget}';
        if (await _remoteSize(target) == item.entry.size) continue;
        log('  ${item.entry.name} → ${item.relTarget}');
        // tail/head slice the NSP in place: no temp copy of a 5 GB file.
        await Shizuku.run(
            'mkdir -p ${shq(target.substring(0, target.lastIndexOf('/')))} && '
            'tail -c +${item.entry.offset + 1} ${shq(nspPath)} | head -c ${item.entry.size} > ${shq(target)}');
        final got = await _remoteSize(target);
        if (got != item.entry.size) {
          await Shizuku.run('rm -f ${shq(target)}');
          throw Exception('Short write for ${item.entry.name}: $got of ${item.entry.size} bytes');
        }
        written++;
      }
      for (final tik in plan.tickets) {
        final key = readTicket(nspPath, tik);
        if (key == null) continue;
        final keysFile = '$dir/keys/title.keys_autogenerated';
        await Shizuku.run(
            'mkdir -p ${shq('$dir/keys')}; '
            '[ -f ${shq(keysFile)} ] || printf "# This file is autogenerated by Yuzu\\n# It serves to store keys that were automatically generated from the normal keys\\n# If you are experiencing issues involving keys, it may help to delete this file\\n \\n" > ${shq(keysFile)}; '
            'grep -qi "^${key.rightsId}" ${shq(keysFile)} || echo "${key.rightsId} = ${key.titleKey}" >> ${shq(keysFile)}');
      }
    }
    return written;
  }
}
